<template><section class="flex h-full min-h-0 flex-col overflow-hidden bg-background"><header class="flex min-h-14 items-center gap-2 border-b px-4"><Button variant="ghost" size="sm" @click="router.push({name:'goal-detail',params:{id:goalId}})"><ArrowLeft class="mr-1 h-4 w-4"/>{{ t('common.back') }}</Button><h1 class="font-semibold">Goal review</h1></header><div class="min-h-0 flex-1 overflow-auto p-4"><div v-if="review" class="mx-auto max-w-3xl space-y-5"><article class="rounded-lg border bg-card p-5"><p class="text-xs text-muted-foreground">{{ formatProductDate(review.reviewedAt) }}</p><p class="mt-3 whitespace-pre-wrap">{{ review.reflection }}</p><div v-if="review.challenges" class="mt-4"><h2 class="text-sm font-medium">Challenges</h2><p class="mt-1 whitespace-pre-wrap text-sm text-muted-foreground">{{ review.challenges }}</p></div><div v-if="review.adjustments" class="mt-4"><h2 class="text-sm font-medium">Adjustments</h2><p class="mt-1 whitespace-pre-wrap text-sm text-muted-foreground">{{ review.adjustments }}</p></div></article><article class="rounded-lg border bg-card p-5"><div class="flex justify-between"><div><p class="text-sm text-muted-foreground">Authoritative progress snapshot</p><p class="text-2xl font-semibold">{{ review.systemContext.overallProgress.endPercentage }}%</p></div><span>{{ signed(review.systemContext.overallProgress.deltaPercentage) }}</span></div><Progress class="mt-3" :model-value="review.systemContext.overallProgress.endPercentage"/><div class="mt-4 space-y-2"><div v-for="kr in review.systemContext.keyResults" :key="kr.keyResultId" class="rounded-md border p-3"><div class="flex justify-between text-sm"><span>{{ kr.title }} <span class="text-muted-foreground">{{ kr.unit ?? '' }}</span></span><span>{{ kr.startPercentage }}% → {{ kr.endPercentage }}%</span></div><div class="mt-2 flex flex-wrap gap-2 text-xs text-muted-foreground"><span v-for="point in kr.trend" :key="`${point.at}-${point.progressPercentage}`">{{ formatProductDate(point.at) }} {{ point.progressPercentage }}%</span></div></div></div><p class="mt-4 text-xs text-muted-foreground">{{ review.systemContext.summary.recordCount }} records · {{ review.systemContext.summary.taskContributionCount }} task contributions</p></article></div></div></section></template>
<script setup lang="ts">import { computed,onMounted } from 'vue';import { useRoute,useRouter } from 'vue-router';import { useI18n } from 'vue-i18n';import { ArrowLeft } from '@lucide/vue';import { Button,Progress } from '@memoflow/ui-vue-shadcn';import { useGoal } from '../composables/useGoal';import { formatProductDate } from '../../../shared/utils/product-time';const route=useRoute();const router=useRouter();const {t}=useI18n();const {goalReviews,getGoalAggregateView}=useGoal();const goalId=String(route.params.goalId??'');const reviewId=String(route.params.reviewId??'');const review=computed(()=>goalReviews.value.find(r=>String(r.id)===reviewId)??null);onMounted(()=>void getGoalAggregateView(goalId));function signed(v:number){return `${v>=0?'+':''}${Math.round(v*100)/100}%`;}</script>
